package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.Zero
var WsOtHours decimal.Decimal = decimal.Zero
var WsGross decimal.Decimal = decimal.Zero
var WsDeptTotal decimal.Decimal = decimal.Zero
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.Zero
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var EmpRecCurrent EmpRec
var empFileLines []string
var empFileIdx int

const picHours = "ZZ9.9"
const picRate = "ZZ9.99"
const picGross = "Z,ZZZ,ZZ9.99"
const picDept = "ZZZ,ZZZ,ZZ9.99"
const picGrand = "ZZ,ZZZ,ZZZ,ZZ9.99"

func isInputDone() bool { return WsEofFlag == "Y" }

func storeInt(val int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if val < 0 {
		abs := -val
		return -(abs % mod)
	}
	return val % mod
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var q decimal.Decimal
	if rounded {
		q = val.Round(scale)
	} else {
		q = val.Truncate(scale)
	}
	scaledAbs := q.Abs().Shift(scale).Truncate(0)
	modBase := decimal.New(1, int32(intDigits)+scale)
	if scaledAbs.Cmp(modBase) >= 0 {
		scaledAbs = scaledAbs.Mod(modBase)
	}
	resultAbs := scaledAbs.Shift(-scale)
	if q.Sign() < 0 {
		resultAbs = resultAbs.Neg()
	}
	return resultAbs
}

func parseDisplayDecimal(s string, scale int32) decimal.Decimal {
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else if ch == ' ' {
			b.WriteRune('0')
		} else {
			b.WriteRune('0')
		}
	}
	ds := b.String()
	if ds == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(ds)
	if err != nil {
		return decimal.Zero
	}
	return d.Shift(-scale)
}

func parseEmpRecLine(line string) EmpRec {
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	var r EmpRec
	r.ErId = line[0:5]
	r.ErDept = line[5:8]
	sHours := line[8:12]
	sRate := line[12:17]
	r.ErHours = parseDisplayDecimal(sHours, 1)
	r.ErRate = parseDisplayDecimal(sRate, 2)
	return r
}

func parseLines(data []byte) []string {
	var lines []string
	start := 0
	for i, b := range data {
		if b == '\n' {
			line := data[start:i]
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			lines = append(lines, string(line))
			start = i + 1
		}
	}
	if start < len(data) {
		line := data[start:]
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		lines = append(lines, string(line))
	}
	if lines == nil {
		lines = []string{}
	}
	return lines
}

func formatEdited(val decimal.Decimal, pic string) string {
	isNeg := val.Sign() < 0
	absVal := val.Abs()
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	scale := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			scale++
		}
	}
	quantized := absVal.Truncate(int32(scale))
	scaledAbs := quantized.Shift(int32(scale)).Truncate(0)
	modBase := decimal.New(1, int32(intDigits+scale))
	if scaledAbs.Cmp(modBase) >= 0 {
		scaledAbs = scaledAbs.Mod(modBase)
	}
	var intPart int64
	var fracPart int64
	pow10Scale := int64(1)
	for i := 0; i < scale; i++ {
		pow10Scale *= 10
	}
	if scale > 0 {
		scaledInt := scaledAbs.IntPart()
		intPart = scaledInt / pow10Scale
		fracPart = scaledInt % pow10Scale
	} else {
		intPart = scaledAbs.IntPart()
	}
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	fracStr := ""
	if scale > 0 {
		fracStr = fmt.Sprintf("%0*d", scale, fracPart)
	}
	picRunes := []rune(intPic)
	resultInt := make([]rune, len(picRunes))
	digitIdx := 0
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			resultInt[i] = rune(intStr[digitIdx])
			digitIdx++
		} else if ch == ',' {
			resultInt[i] = ','
		} else {
			resultInt[i] = ch
		}
	}
	suppressed := true
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			dig := resultInt[i]
			if ch == 'Z' && suppressed && dig == '0' {
				resultInt[i] = ' '
			} else {
				suppressed = false
			}
		} else if ch == ',' {
			if suppressed {
				resultInt[i] = ' '
			}
		}
	}
	var final string
	if dotIdx >= 0 {
		final = string(resultInt) + "." + fracStr
	} else {
		final = string(resultInt)
	}
	if isNeg {
		runes := []rune(final)
		firstDigitIdx := -1
		for idx, r := range runes {
			if r >= '0' && r <= '9' {
				firstDigitIdx = idx
				break
			}
		}
		if firstDigitIdx != -1 {
			replaceIdx := -1
			for idx := firstDigitIdx - 1; idx >= 0; idx-- {
				if runes[idx] == ' ' {
					replaceIdx = idx
					break
				}
			}
			if replaceIdx != -1 {
				runes[replaceIdx] = '-'
			} else {
				runes = append([]rune{'-'}, runes...)
				if len(runes) > len(pic) {
					runes = runes[len(runes)-len(pic):]
				}
			}
			final = string(runes)
		}
	}
	return final
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			empFileLines = []string{}
		} else {
			fmt.Fprintf(os.Stderr, "open error: %v\n", err)
			os.Exit(1)
		}
	} else {
		empFileLines = parseLines(data)
	}
	empFileIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if WsFirstFlag != "Y" {
		DeptBreakPara()
	}
	GrandPara()
}

func ReadPara() {
	if empFileIdx >= len(empFileLines) {
		WsEofFlag = "Y"
		return
	}
	raw := empFileLines[empFileIdx]
	empFileIdx++
	if len(raw) < 17 {
		raw = raw + strings.Repeat(" ", 17-len(raw))
	} else if len(raw) > 17 {
		raw = raw[:17]
	}
	EmpRecCurrent = parseEmpRecLine(raw)
}

func ProcessPara() {
	if WsFirstFlag == "Y" {
		WsPrevDept = EmpRecCurrent.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecCurrent.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = EmpRecCurrent.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	if EmpRecCurrent.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = storeDecimal(decimal.NewFromInt(40), 3, 1, false)
		diff := EmpRecCurrent.ErHours.Sub(decimal.NewFromInt(40))
		WsOtHours = storeDecimal(diff, 3, 1, false)
	} else {
		WsRegHours = storeDecimal(EmpRecCurrent.ErHours, 3, 1, false)
		WsOtHours = storeDecimal(decimal.Zero, 3, 1, false)
	}
	onePointFive := decimal.New(15, -1)
	part1 := WsRegHours.Mul(EmpRecCurrent.ErRate)
	part2 := WsOtHours.Mul(EmpRecCurrent.ErRate).Mul(onePointFive)
	grossCalc := part1.Add(part2)
	WsGross = storeDecimal(grossCalc, 7, 2, true)
	newDeptTotal := WsDeptTotal.Add(WsGross)
	WsDeptTotal = storeDecimal(newDeptTotal, 9, 2, false)
	WsDeptCount = storeInt(WsDeptCount+1, 3)
	newGrandTotal := WsGrandTotal.Add(WsGross)
	WsGrandTotal = storeDecimal(newGrandTotal, 11, 2, false)
	WsGrandCount = storeInt(WsGrandCount+1, 5)
	WsHoursEd = formatEdited(EmpRecCurrent.ErHours, picHours)
	WsRateEd = formatEdited(EmpRecCurrent.ErRate, picRate)
	WsGrossEd = formatEdited(WsGross, picGross)
	line := EmpRecCurrent.ErId + " " + EmpRecCurrent.ErDept + " " + WsHoursEd + " " + WsRateEd + " " + WsGrossEd
	fmt.Fprintln(os.Stdout, line)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, picDept)
	countStr := fmt.Sprintf("%03d", WsDeptCount)
	line := "  DEPT " + WsPrevDept + " EMPLOYEES: " + countStr + " TOTAL: " + WsDeptEd
	fmt.Fprintln(os.Stdout, line)
	WsDeptTotal = storeDecimal(decimal.Zero, 9, 2, false)
	WsDeptCount = storeInt(0, 3)
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, picGrand)
	countStr := fmt.Sprintf("%05d", WsGrandCount)
	line := "GRAND TOTAL (" + countStr + "): " + WsGrandEd
	fmt.Fprintln(os.Stdout, line)
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = "   "
	WsRegHours = decimal.Zero
	WsOtHours = decimal.Zero
	WsGross = decimal.Zero
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
	WsGrandTotal = decimal.Zero
	WsGrandCount = 0
	MainPara()
}
